// Runs only against an explicitly supplied snapshot generated by prepare-bundled.php.
// Never infer that a preparation snapshot is the current deployed database.
func TestBundledSourceRehearsal(t *testing.T) {
	dir := os.Getenv("MIGRATION_BUNDLED_SNAPSHOT")
	if dir == "" {
		t.Skip("MIGRATION_BUNDLED_SNAPSHOT not configured")
	}
	raw, e := os.ReadFile(filepath.Join(dir, "resolved-config.private.json"))
	if e != nil {
		t.Fatal("bundled snapshot config unavailable")
	}
	var config struct {
		DSN string `json:"dsn"`
		Key string `json:"app_key"`
	}
	if e = json.Unmarshal(raw, &config); e != nil || !regexp.MustCompile(`(?:^|;)dbname=bundled_[a-f0-9]+_test(?:;|$)`).MatchString(strings.TrimPrefix(config.DSN, "mysql:")) {
		t.Fatal("only an explicitly generated bundled_*_test source is accepted")
	}
	crypt, e := legacy.New(config.Key)
	if e != nil {
		t.Fatal("bundled encryption key invalid")
	}
	p := testdb.Open(t)
	ctx := context.Background()
	report, e := Import(ctx, p, dir)
	if e != nil {
		t.Fatal(e)
	}
	if report.ReadyForCutover || report.Reused {
		t.Fatal("bundled rehearsal misreported readiness")
	}
	if report.Imported["university_books"] != 7991 || report.Archived["directory_entries"] != 670 {
		t.Fatal("bundled source population mismatch")
	}
	var tables int
	if e = p.QueryRow(ctx, `SELECT count(*) FROM migration_import_tables`).Scan(&tables); e != nil || tables != 58 {
		t.Fatal("source tables not completely archived", tables, e)
	}
	for _, table := range []string{"admins", "users", "admin_sessions", "admin_access_grants", "work_jobs", "announcement_dispatches"} {
		var count int
		if e = p.QueryRow(ctx, "SELECT count(*) FROM "+table).Scan(&count); e != nil || count != 0 {
			t.Fatal("bundled fixture activated runtime identity or delivery", table, count, e)
		}
	}
	var state string
	if e = p.QueryRow(ctx, `SELECT value FROM settings WHERE name='bot_state'`).Scan(&state); e != nil || state != `"off"` {
		t.Fatal("bundled bot is not off", e)
	}
	var paused bool
	if e = p.QueryRow(ctx, `SELECT paused FROM queue_control`).Scan(&paused); e != nil || !paused {
		t.Fatal("bundled queue is not paused", e)
	}
	contents := bundledArchiveRows(t, p, "contents")
	all := map[int64]map[string]*string{}
	published := map[int64]map[string]*string{}
	drafts := map[int64]map[string]*string{}
	for _, row := range contents {
		id, e := strconv.ParseInt(bundledCell(t, row, "id"), 10, 64)
		if e != nil {
			t.Fatal("invalid archived content ID")
		}
		all[id] = row
		switch bundledCell(t, row, "status") {
		case "published":
			published[id] = row
		case "draft":
			drafts[id] = row
		default:
			t.Fatal("unexpected bundled content status")
		}
	}
	if len(all) != 670 || len(published) != 55 || len(drafts) != 615 {
		t.Fatal("unexpected bundled content publication counts", len(all), len(published), len(drafts))
	}
	var active int
	if e = p.QueryRow(ctx, `SELECT count(*) FROM contents`).Scan(&active); e != nil || active != 670 {
		t.Fatal("operational contents count changed", active, e)
	}
	if e = p.QueryRow(ctx, `SELECT count(*) FROM contents WHERE status='published'`).Scan(&active); e != nil || active != 55 {
		t.Fatal("publication count changed", active, e)
	}
	for id, row := range all {
		var title, body, metadata, status string
		if e = p.QueryRow(ctx, `SELECT title,body,metadata,status FROM contents WHERE id=$1`, id).Scan(&title, &body, &metadata, &status); e != nil {
			t.Fatal("PHP content ID was not preserved", e)
		}
		if title != bundledCell(t, row, "title") || body != bundledCell(t, row, "body") || metadata != bundledCell(t, row, "metadata") || status != bundledCell(t, row, "status") {
			t.Fatal("content bytes/state changed")
		}
	}
	entries := bundledArchiveRows(t, p, "directory_entries")
	reviewCount, publishedCount, personalFields := 0, 0, 0
	for _, entry := range entries {
		encrypted := bundledCell(t, entry, "payload_enc")
		clear, e := crypt.Decrypt(encrypted)
		if e != nil {
			t.Fatal("archived directory record no longer decrypts")
		}
		var record map[string]any
		if json.Unmarshal(clear, &record) != nil {
			t.Fatal("invalid directory record")
		}
		fields, _ := record["fields"].([]any)
		for _, v := range fields {
			field, _ := v.(map[string]any)
			if field["scope"] == "personal" {
				personalFields++
			}
		}
		id, e := strconv.ParseInt(bundledCell(t, entry, "content_id"), 10, 64)
		if e != nil {
			t.Fatal("directory entry lacks linked PHP content ID")
		}
		source, ok := all[id]
		if !ok {
			t.Fatal("directory link points to missing content")
		}
		var meta map[string]any
		if json.Unmarshal([]byte(bundledCell(t, source, "metadata")), &meta) != nil {
			t.Fatal("invalid directory metadata")
		}
		contacts, _ := meta["directory_contacts"].([]any)
		safe := map[string]bool{}
		for _, v := range fields {
			field, _ := v.(map[string]any)
			trust, _ := field["trust"].(string)
			historical, _ := field["historical"].(bool)
			conflict, _ := field["conflict"].(bool)
			if field["scope"] != "personal" && !historical && !conflict && (trust == "official" || trust == "announced") {
				value := fmt.Sprint(field["value"])
				if field["type"] == "phone" {
					value = catalog.Normalize(value)
					value = strings.NewReplacer(" ", "", "(", "", ")", "", "-", "").Replace(value)
					if strings.HasPrefix(value, "+98") {
						value = "0" + strings.TrimPrefix(value, "+98")
					}
					if strings.HasPrefix(value, "0098") {
						value = "0" + strings.TrimPrefix(value, "0098")
					}
				}
				safe[fmt.Sprint(field["type"])+"\x00"+value] = true
			}
		}
		// Normalized values recorded by the PHP publisher must originate in safe fields.
		review, _ := record["review"].(map[string]any)
		indices, _ := review["selected_indices"].([]any)
		values := review["field_values"]
		for _, v := range indices {
			n, ok := v.(float64)
			if !ok {
				t.Fatal("invalid selected index")
			}
			index := int(n)
			if index < 0 || index >= len(fields) {
				t.Fatal("invalid selected field index")
			}
			field, _ := fields[index].(map[string]any)
			trust, _ := field["trust"].(string)
			historical, _ := field["historical"].(bool)
			conflict, _ := field["conflict"].(bool)
			if field["scope"] == "personal" || historical || conflict || trust != "official" && trust != "announced" {
				t.Fatal("PHP selected a private/review field")
			}
			var normalized any
			switch x := values.(type) {
			case []any:
				if index < len(x) {
					normalized = x[index]
				}
			case map[string]any:
				normalized = x[strconv.Itoa(index)]
			}
			if normalized != nil {
				safe[fmt.Sprint(field["type"])+"\x00"+fmt.Sprint(normalized)] = true
			}
		}
		for _, v := range contacts {
			field, _ := v.(map[string]any)
			if !safe[fmt.Sprint(field["type"])+"\x00"+fmt.Sprint(field["value"])] {
				t.Fatal("active content contains a private/historical/conflicting directory field")
			}
		}
		switch bundledCell(t, entry, "state") {
		case "review":
			reviewCount++
			if _, ok := drafts[id]; !ok {
				t.Fatal("review directory record was published")
			}
		case "published":
			publishedCount++
			if _, ok := published[id]; !ok || len(contacts) == 0 {
				t.Fatal("published directory record lacks public contacts")
			}
		default:
			t.Fatal("unexpected directory state")
		}

	}
	if reviewCount != 615 || publishedCount != 55 || personalFields == 0 {
		t.Fatal("directory review/private population was not preserved", reviewCount, publishedCount, personalFields)
	}
	verifyBundledBooks(t, p)
	tx, e := p.Begin(ctx)
	if e != nil {
		t.Fatal(e)
	}
	for _, kind := range []string{"professors", "contacts", "links"} {
		page, e := catalog.Search(ctx, tx, kind, "", 0, nil, true)
		expectedTotal := map[string]int{"professors": 0, "contacts": 45, "links": 10}[kind]
		if e != nil || len(page.Rows) > 10 || page.Total != expectedTotal {
			t.Fatal("catalog search/publication filter failed", kind, page.Total, e)
		}
		for _, c := range page.Rows {
			if _, ok := published[c.ID]; !ok {
				t.Fatal("search exposed an unpublished source record")
			}
		}
	}
	for id := range drafts {
		if _, err := catalog.ReadPublished(ctx, tx, id, nil, true); err != catalog.ErrMissing {
			t.Fatal("draft passed published-content policy", err)
		}
		break
	}
	page, e := catalog.Books(ctx, tx, "", "", 0)
	if e != nil || page.Total != 7991 || len(page.Rows) != 10 || page.Pages != 800 {
		t.Fatal("book pagination failed", page.Total, page.Pages, len(page.Rows), e)
	}
	if len(page.Rows) > 0 {
		first := page.Rows[0]
		details, e := catalog.GetBook(ctx, tx, first.ID)
		if e != nil || details.Title != first.Title || !reflect.DeepEqual(details.Details, first.Details) {
			t.Fatal("book detail lookup changed values", e)
		}
		category, e := catalog.Books(ctx, tx, "", first.Category, 0)
		if e != nil || len(category.Rows) > 10 || category.Total < 1 {
			t.Fatal("category listing failed", e)
		}
		for _, b := range category.Rows {
			if b.Category != first.Category {
				t.Fatal("category filter returned another category")
			}
		}
		words := strings.Fields(first.Title)
		if len(words) > 0 {
			search, e := catalog.Books(ctx, tx, words[0], "", 0)
			if e != nil || search.Total < 1 || len(search.Rows) > 10 {
				t.Fatal("book search failed", e)
			}
		}
	}
	tx.Rollback(ctx)
	again, e := Import(ctx, p, dir)
	if e != nil || !again.Reused {
		t.Fatal("bundled snapshot replay not idempotent", e)
	}
	var count int
	if e = p.QueryRow(ctx, `SELECT count(*) FROM university_books`).Scan(&count); e != nil || count != 7991 {
		t.Fatal("replay changed book count", count, e)
	}
	file, e := os.Open("../../../database/seed/university-books.jsonl.gz")
	if e != nil {
		t.Fatal(e)
	}
	defer file.Close()
	tx, e = p.Begin(ctx)
	if e != nil {
		t.Fatal(e)
	}
	defer tx.Rollback(ctx)
	added, e := catalog.SeedBooks(ctx, tx, file)
	if e != nil || added != 0 {
		t.Fatal("seeding recreated imported books", added, e)
	}
	t.Log("bundled source: 58 tables archived, 7991 books preserved, 55 public/615 draft+review directory records verified; no runtime identities or sends")
}

func bundledArchiveRows(t *testing.T, p *pgxpool.Pool, table string) []map[string]*string {
	t.Helper()
	rows, e := p.Query(context.Background(), `SELECT cells FROM migration_import_rows WHERE source_table=$1 ORDER BY row_number`, table)
	if e != nil {
		t.Fatal(e)
	}
	defer rows.Close()
	out := []map[string]*string{}
	for rows.Next() {
		var raw string
		if e = rows.Scan(&raw); e != nil {
			t.Fatal(e)
		}
		var row map[string]*string
		if json.Unmarshal([]byte(raw), &row) != nil {
			t.Fatal("invalid archived cell data")
		}
		out = append(out, row)
	}
	if e = rows.Err(); e != nil {
		t.Fatal(e)
	}
	return out
}
func bundledCell(t *testing.T, row map[string]*string, key string) string {
	t.Helper()
	v := row[key]
	if v == nil {
		return ""
	}
	raw, e := base64.StdEncoding.DecodeString(*v)
	if e != nil {
		t.Fatal("invalid archived cell encoding")
	}
	return string(raw)
}
func verifyBundledBooks(t *testing.T, p *pgxpool.Pool) {
	t.Helper()
	type book struct {
		Key     string         `json:"key"`
		Title   string         `json:"title"`
		Details map[string]any `json:"details"`
	}
	expected := map[string]book{}
	f, e := os.Open("../../../database/seed/university-books.jsonl.gz")
	if e != nil {
		t.Fatal(e)
	}
	defer f.Close()
	gz, e := gzip.NewReader(f)
	if e != nil {
		t.Fatal(e)
	}
	defer gz.Close()
	scanner := bufio.NewScanner(gz)
	scanner.Buffer(make([]byte, 64<<10), 4<<20)
	for scanner.Scan() {
		var b book
		if json.Unmarshal(scanner.Bytes(), &b) != nil {
			t.Fatal("invalid bundled book seed")
		}
		if _, exists := expected[b.Key]; exists {
			t.Fatal("duplicate bundled book key")
		}
		expected[b.Key] = b
	}
	if e = scanner.Err(); e != nil {
		t.Fatal(e)
	}
	if len(expected) != 7991 {
		t.Fatal("bundled seed count changed", len(expected))
	}
	rows, e := p.Query(context.Background(), `SELECT id,source_key,title,details FROM university_books ORDER BY id`)
	if e != nil {
		t.Fatal(e)
	}
	count := 0
	activeIDs := map[string]int64{}
	for rows.Next() {
		var id int64
		var key, title, raw string
		if e = rows.Scan(&id, &key, &title, &raw); e != nil {
			rows.Close()
			t.Fatal(e)
		}
		b, exists := expected[key]
		if !exists || title != b.Title {
			rows.Close()
			t.Fatal("book source key/title changed")
		}
		var details map[string]any
		if json.Unmarshal([]byte(raw), &details) != nil || !reflect.DeepEqual(details, b.Details) {
			rows.Close()
			t.Fatal("book details changed")
		}
		activeIDs[key] = id
		count++
	}
	e = rows.Err()
	rows.Close()
	if e != nil || count != 7991 {
		t.Fatal("book row count mismatch", count, e)
	}
	archived := bundledArchiveRows(t, p, "university_books")
	if len(archived) != 7991 {
		t.Fatal("book archive count mismatch", len(archived))
	}
	for _, row := range archived {
		id, e := strconv.ParseInt(bundledCell(t, row, "id"), 10, 64)
		if e != nil || activeIDs[bundledCell(t, row, "source_key")] != id {
			t.Fatal("original PHP book ID changed")
		}
	}
}
